`ifndef __GUARD_RANDOM_UART_RX_SEQ_SV__
`define __GUARD_RANDOM_UART_RX_SEQ_SV__ 0

`include "apb_uart_uvm_tb/sequence/apb_uart_base_seq.sv"

class random_uart_rx_seq extends apb_uart_base_seq;

  `uvm_object_utils(random_uart_rx_seq)

  // Store bytes generated by this sequence invocation.
  bit [7:0] driven_data[$];
  int unsigned num_transactions;

  function new(string name = "random_uart_rx_seq");
    super.new(name);
  endfunction : new


  virtual task body();

    bit [7:0] tx_data;
    time bit_time;

    driven_data.delete();

    // Get transaction count from configuration database.
    if (!uvm_config_db#(int)::get(
            uvm_root::get(), "parameter", "RANDOM_UART_RX_SEQ_LENGTH", num_transactions
        ))
      num_transactions = 10;

    `uvm_info(get_type_name(), $sformatf("Starting DUT UART TX test with %0d bytes",
                                         num_transactions), UVM_LOW)

    // UART configuration
    apb_write(6'h04, 32'h00030398);

    // Enable TX only
    apb_write(6'h00, 32'h00000008);

    bit_time = 1s / 108695;

    // Generate and transmit randomized bytes.
    repeat (num_transactions) begin

      tx_data = $urandom();

      driven_data.push_back(tx_data);

      // TX request
      apb_write(6'h10, 32'h80000001);

      // TX data
      apb_write(6'h1C, {24'h0, tx_data});

      `uvm_info(get_type_name(), $sformatf("TX byte generated: 0x%02h", tx_data), UVM_MEDIUM)

      #(10 * bit_time);

    end

    `uvm_info(get_type_name(), $sformatf("All TX data writes completed. Total bytes: %0d",
                                         driven_data.size()), UVM_LOW)

  endtask : body

endclass : random_uart_rx_seq

`endif
